    /**
     * Seed Mindanao provinces and their cities/municipalities.
     */
    public function run(): void
    {
        foreach (json_decode(self::LOCATIONS_JSON, true, flags: JSON_THROW_ON_ERROR) as $provinceData) {
            $province = Province::query()->updateOrCreate(
                ['code' => $provinceData['code']],
                [
                    'name' => $provinceData['name'],
                    'region_code' => $provinceData['region_code'],
                    'region_name' => $provinceData['region_name'],
                    'is_active' => true,
                ],
            );

            $activeMunicipalityCodes = collect($provinceData['municipalities'])->pluck('code')->all();

            Municipality::query()
                ->where('province_id', $province->id)
                ->whereNotIn('code', $activeMunicipalityCodes)
                ->update(['is_active' => false]);

            foreach ($provinceData['municipalities'] as $municipalityData) {
                Municipality::query()->updateOrCreate(
                    ['code' => $municipalityData['code']],
                    [
                        'province_id' => $province->id,
                        'name' => $municipalityData['name'],
                        'type' => $municipalityData['type'],
                        'is_active' => true,
                    ],
                );
            }
        }
    }
}
